package main

import (
	"fmt"
	"os/exec"
)

// QuerySLBAndExport executes the aliyun CLI command to describe SLB,
// processes the output with jq, and saves it to the specified file.
// Returns the stdout of the command pipeline and any error encountered.
func QuerySLBAndExport(loadBalancerName string, outputFile string) (string, error) {
	// Use exec.Command with direct arguments to avoid shell injection.
	// The pipeline is constructed using Go's io.Pipe or by chaining commands.
	// Here we use a shell to run the pipeline, but with proper argument passing
	// to prevent injection. The loadBalancerName is passed as an argument to the
	// aliyun command, not interpolated into the shell string.

	// Safely build the shell command string using single quotes for the output file.
	// To prevent injection in outputFile, we replace single quotes with '\'' sequence.
	safeOutputFile := ""
	for _, ch := range outputFile {
		if ch == '\'' {
			safeOutputFile += "'\\''"
		} else {
			safeOutputFile += string(ch)
		}
	}

	// Build the aliyun command string with safe arguments
	aliyunCmdStr := "aliyun slb DescribeLoadBalancers --LoadBalancerName"
	// We pass loadBalancerName as a separate argument to sh -c, using "$1"
	// This avoids any shell interpretation of the name.
	shellCmd := fmt.Sprintf("%s \"$1\" | jq '.LoadBalancers.LoadBalancer[]' > '%s'",
		aliyunCmdStr, safeOutputFile)

	// Execute with sh -c, passing loadBalancerName as positional parameter $1
	cmd := exec.Command("sh", "-c", shellCmd, "sh", loadBalancerName)

	// Capture stdout and stderr
	outputBytes, err := cmd.CombinedOutput()
	outputStr := string(outputBytes)

	if err != nil {
		return outputStr, fmt.Errorf("command failed: %w, output: %s", err, outputStr)
	}

	return outputStr, nil
}

