package main

import (
	"fmt"
	"os"
	"os/exec"
)

// QuerySLBAndExport queries SLB information using aliyun CLI and exports formatted output to a file.
// It executes: aliyun slb DescribeLoadBalancers --LoadBalancerName <loadBalancerName> | jq '.LoadBalancers.LoadBalancer[]' > <outputFile>
func QuerySLBAndExport(loadBalancerName string, outputFile string) (string, error) {
	// Build the aliyun command
	aliyunCmd := exec.Command("aliyun", "slb", "DescribeLoadBalancers", "--LoadBalancerName", loadBalancerName)

	// Build the jq command
	jqCmd := exec.Command("jq", ".LoadBalancers.LoadBalancer[]")

	// Create a pipe to connect aliyun stdout to jq stdin
	pipeReader, pipeWriter, err := os.Pipe()
	if err != nil {
		return "", fmt.Errorf("failed to create pipe: %w", err)
	}
	defer pipeReader.Close()
	defer pipeWriter.Close()

	// Set aliyun command's stdout to the pipe writer
	aliyunCmd.Stdout = pipeWriter

	// Set jq command's stdin to the pipe reader
	jqCmd.Stdin = pipeReader

	// Capture jq's stdout
	jqCmd.Stdout = os.Stdout // temporary, will be replaced
	var jqOutput []byte

	// Start both commands
	if err := jqCmd.Start(); err != nil {
		return "", fmt.Errorf("failed to start jq command: %w", err)
	}

	if err := aliyunCmd.Start(); err != nil {
		return "", fmt.Errorf("failed to start aliyun command: %w", err)
	}

	// Wait for aliyun to finish first
	if err := aliyunCmd.Wait(); err != nil {
		pipeWriter.Close()
		jqCmd.Wait()
		return "", fmt.Errorf("aliyun command failed: %w", err)
	}

	// Close the pipe writer so jq can finish reading
	pipeWriter.Close()

	// Read jq output
	jqOutput, err = jqCmd.Output()
	if err != nil {
		return "", fmt.Errorf("jq command failed: %w", err)
	}

	// Write jq output to the output file
	if err := os.WriteFile(outputFile, jqOutput, 0644); err != nil {
		return "", fmt.Errorf("failed to write output file: %w", err)
	}

	result := string(jqOutput)
	return result, nil
}

func main() {
	// Example usage
	result, err := QuerySLBAndExport("my-load-balancer", "output.json")
	if err != nil {
		fmt.Printf("Error: %v\n", err)
		return
	}
	fmt.Printf("Result:\n%s\n", result)
}

