    if err != nil {
        return "", fmt.Errorf("failed to create stdin pipe for jq: %w", err)
    }

    // Write aliyun output to jq's stdin in a goroutine
    go func() {
        defer stdinPipe.Close()
        stdinPipe.Write(aliyunOutput)
    }()

    jqOutput, err := jqCmd.Output()
    if err != nil {
        if exitErr, ok := err.(*exec.ExitError); ok {
            return "", fmt.Errorf("jq command failed: %w, stderr: %s", err, string(exitErr.Stderr))
        }
        return "", fmt.Errorf("jq command failed: %w", err)
    }

    // Step 3: Write the jq output to the specified file
    err = os.WriteFile(outputFile, jqOutput, 0644)
    if err != nil {
        return "", fmt.Errorf("failed to write output file: %w", err)
    }

    return string(jqOutput), nil
}

