	jqCmd := exec.Command("jq", ".LoadBalancers.LoadBalancer[]")

	// Create a pipe between aliyun and jq
	jqCmd.Stdin, _ = aliyunCmd.StdoutPipe()
	jqCmd.Stdout = nil // Will be captured

	// Start jq first
	if err := jqCmd.Start(); err != nil {
		return "", fmt.Errorf("failed to start jq: %w", err)
	}

	// Run aliyun command
	if err := aliyunCmd.Run(); err != nil {
		jqCmd.Wait()
		return "", fmt.Errorf("failed to run aliyun command: %w", err)
	}

	// Capture jq output
	jqOutput, err := jqCmd.Output()
	if err != nil {
		return "", fmt.Errorf("failed to get jq output: %w", err)
	}

	// Write output to file
	if err := os.WriteFile(outputFile, jqOutput, 0644); err != nil {
		return "", fmt.Errorf("failed to write output file: %w", err)
	}

	result := string(jqOutput)
	return result, nil
}

func main() {
	// Example usage
