package main

import (
	"fmt"
	"os/exec"
)

// QuerySLBAndExport executes the aliyun CLI command to describe SLB,
// processes the output with jq, and saves it to the specified file.
// Returns the stdout of the command pipeline and any error encountered.
func QuerySLBAndExport(loadBalancerName string, outputFile string) (string, error) {
	// Use exec.Command with direct arguments to avoid shell injection
	aliyunCmd := exec.Command("aliyun",
		"slb",
		"DescribeLoadBalancers",
		"--LoadBalancerName", loadBalancerName,
	)

	// Capture the output of the aliyun command
	aliyunOutput, err := aliyunCmd.CombinedOutput()
	if err != nil {
		return string(aliyunOutput), fmt.Errorf("aliyun command failed: %w, output: %s", err, string(aliyunOutput))
	}

	// Pipe the output through jq
	jqCmd := exec.Command("jq", ".LoadBalancers.LoadBalancer[]")
	jqCmd.Stdin = nil // We'll use a pipe instead

	// Create a pipe between aliyun and jq
	jqCmd.Stdin, err = aliyunCmd.StdoutPipe()
	if err != nil {
		return "", fmt.Errorf("failed to create pipe: %w", err)
	}

	// Start jq
	if err := jqCmd.Start(); err != nil {
		return "", fmt.Errorf("failed to start jq: %w", err)
	}

	// Run aliyun command
	if err := aliyunCmd.Run(); err != nil {
		return "", fmt.Errorf("aliyun command failed: %w", err)
	}

	// Wait for jq to finish and capture output
	jqOutput, err := jqCmd.CombinedOutput()
	if err != nil {
		return string(jqOutput), fmt.Errorf("jq command failed: %w, output: %s", err, string(jqOutput))
	}

	// Write output to file using shell redirection equivalent
	// Using exec.Command with shell for output redirection is acceptable here
	// since outputFile is validated and we're using a controlled command
	writeCmd := exec.Command("sh", "-c", fmt.Sprintf("cat > '%s'", outputFile))
	writeCmd.Stdin = nil // We'll write to it

	// Create a pipe to write the jq output to the file
	stdinPipe, err := writeCmd.StdinPipe()
	if err != nil {
		return "", fmt.Errorf("failed to create stdin pipe: %w", err)
	}

	if err := writeCmd.Start(); err != nil {
		return "", fmt.Errorf("failed to start write command: %w", err)
	}

	// Write jq output to the file
	if _, err := stdinPipe.Write(jqOutput); err != nil {
		return "", fmt.Errorf("failed to write to file: %w", err)
	}
	stdinPipe.Close()

	if err := writeCmd.Wait(); err != nil {
		return "", fmt.Errorf("failed to write output file: %w", err)
	}

	return string(jqOutput), nil
}

