// QuerySLBAndExport queries SLB information using aliyun CLI and exports formatted output to a file.
// It runs: aliyun slb DescribeLoadBalancers --LoadBalancerName <loadBalancerName> | jq '.LoadBalancers.LoadBalancer[]' > <outputFile>
func QuerySLBAndExport(loadBalancerName string, outputFile string) (string, error) {
	// Build the aliyun command
	aliyunCmd := exec.Command("aliyun", "slb", "DescribeLoadBalancers", "--LoadBalancerName", loadBalancerName)

	// Build the jq command
	jqCmd := exec.Command("jq", ".LoadBalancers.LoadBalancer[]")

	// Create a pipe between aliyun and jq
	pipeReader, pipeWriter, err := os.Pipe()
	if err != nil {
		return "", fmt.Errorf("failed to create pipe: %w", err)
	}

	// Set aliyun stdout to the pipe writer
	aliyunCmd.Stdout = pipeWriter
	aliyunCmd.Stderr = &strings.Builder{}

	// Set jq stdin to the pipe reader
	jqCmd.Stdin = pipeReader

	// Capture jq stderr
	jqStderr := &strings.Builder{}
	jqCmd.Stderr = jqStderr

	// Open output file for writing
	outFile, err := os.Create(outputFile)
	if err != nil {
		pipeReader.Close()
		pipeWriter.Close()
		return "", fmt.Errorf("failed to create output file: %w", err)
	}
	defer outFile.Close()

	// Set jq stdout to the output file
	jqCmd.Stdout = outFile

	// Start aliyun command
	if err := aliyunCmd.Start(); err != nil {
		pipeReader.Close()
		pipeWriter.Close()
