package main

import (
	"fmt"
	"os/exec"
	"strings"
)

// QuerySLBAndExport executes the aliyun CLI command to describe SLB,
// processes the output with jq, and saves it to the specified file.
// Returns the stdout of the command pipeline and any error encountered.
func QuerySLBAndExport(loadBalancerName string, outputFile string) (string, error) {
	// Basic input validation to prevent obvious shell injection
	if strings.ContainsAny(loadBalancerName, "`$\n\r\t|>") || strings.ContainsAny(outputFile, "`$\n\r\t|>") {
		return "", fmt.Errorf("invalid characters in input parameters")
	}

	// Build the command pipeline using exec.Command with pipes
	aliyunCmd := exec.Command("aliyun", "slb", "DescribeLoadBalancers", "--LoadBalancerName", loadBalancerName)
	jqCmd := exec.Command("jq", ".LoadBalancers.LoadBalancer[]")

	// Create pipe between aliyun and jq
	jqCmd.Stdin, _ = aliyunCmd.StdoutPipe()
	jqCmd.Stdout = nil // stdout will be captured via CombinedOutput

	// Start jq first
	if err := jqCmd.Start(); err != nil {
		return "", fmt.Errorf("failed to start jq: %w", err)
	}

	// Run aliyun command
	aliyunOutput, aliyunErr := aliyunCmd.CombinedOutput()
	if aliyunErr != nil {
		return string(aliyunOutput), fmt.Errorf("aliyun command failed: %w, output: %s", aliyunErr, string(aliyunOutput))
	}

	// Wait for jq to finish and capture its output
	jqOutput, jqErr := jqCmd.CombinedOutput()
	if jqErr != nil {
		return string(jqOutput), fmt.Errorf("jq command failed: %w, output: %s", jqErr, string(jqOutput))
	}

	// Write jq output to file using shell redirection equivalent
	writeCmd := exec.Command("sh", "-c", fmt.Sprintf("cat > '%s'", outputFile))
	writeCmd.Stdin = strings.NewReader(string(jqOutput))
	writeOutput, writeErr := writeCmd.CombinedOutput()
	if writeErr != nil {
		return string(writeOutput), fmt.Errorf("failed to write output file: %w, output: %s", writeErr, string(writeOutput))
	}

	return string(jqOutput), nil
}

