package main

import (
    "fmt"
    "os"
    "os/exec"
)

// QuerySLBAndExport executes the aliyun CLI command to describe SLB,
// processes the output with jq, and saves it to the specified file.
// Returns the stdout of the command pipeline and any error encountered.
func QuerySLBAndExport(loadBalancerName string, outputFile string) (string, error) {
    // Validate input parameters are not empty
    if loadBalancerName == "" {
        return "", fmt.Errorf("loadBalancerName cannot be empty")
    }
    if outputFile == "" {
        return "", fmt.Errorf("outputFile cannot be empty")
    }

    // Execute aliyun command with arguments directly (no shell injection)
    aliyunCmd := exec.Command("aliyun",
        "slb",
        "DescribeLoadBalancers",
        "--LoadBalancerName", loadBalancerName,
    )

    aliyunOutput, err := aliyunCmd.StdoutPipe()
    if err != nil {
        return "", fmt.Errorf("failed to create stdout pipe for aliyun: %w", err)
    }
    aliyunCmd.Stderr = nil // stderr will be captured via CombinedOutput pattern

    // Execute jq command with the aliyun output as stdin
    jqCmd := exec.Command("jq", ".LoadBalancers.LoadBalancer[]")
    jqCmd.Stdin = aliyunOutput

    // Start aliyun command
    if err := aliyunCmd.Start(); err != nil {
        return "", fmt.Errorf("failed to start aliyun command: %w", err)
    }

    // Capture combined output from jq
    outputBytes, err := jqCmd.CombinedOutput()
    outputStr := string(outputBytes)

    // Wait for aliyun to finish
    if waitErr := aliyunCmd.Wait(); waitErr != nil {
        if err != nil {
            return outputStr, fmt.Errorf("aliyun command failed: %w, jq error: %v, output: %s", waitErr, err, outputStr)
        }
        return outputStr, fmt.Errorf("aliyun command failed: %w, output: %s", waitErr, outputStr)
    }

    if err != nil {
        return outputStr, fmt.Errorf("jq command failed: %w, output: %s", err, outputStr)
    }

    // Write the output to the file using Go's standard library
    // This avoids shell injection via outputFile parameter
    if err := os.WriteFile(outputFile, []byte(outputStr), 0644); err != nil {
        return outputStr, fmt.Errorf("failed to write output file: %w", err)
    }

    return outputStr, nil
}

