package main

import (
    "fmt"
    "os"
    "os/exec"
)

// QuerySLBAndExport executes the aliyun CLI command to describe SLB,
// processes the output with jq, and saves it to the specified file.
// Returns the stdout of the command pipeline and any error encountered.
func QuerySLBAndExport(loadBalancerName string, outputFile string) (string, error) {
    // Validate that outputFile is not empty
    if outputFile == "" {
        return "", fmt.Errorf("output file path cannot be empty")
    }

    // Step 1: Execute aliyun CLI command with the loadBalancerName as a direct argument
    aliyunCmd := exec.Command("aliyun", "slb", "DescribeLoadBalancers", "--LoadBalancerName", loadBalancerName)

    // Capture stdout of aliyun command
    aliyunOutput, err := aliyunCmd.Output()
    if err != nil {
        if exitErr, ok := err.(*exec.ExitError); ok {
            return "", fmt.Errorf("aliyun command failed: %w, stderr: %s", err, string(exitErr.Stderr))
        }
        return "", fmt.Errorf("failed to execute aliyun command: %w", err)
    }

    // Step 2: Pipe the output through jq
    jqCmd := exec.Command("jq", ".LoadBalancers.LoadBalancer[]")
    jqCmd.Stdin = bytesReader(aliyunOutput)

    jqOutput, err := jqCmd.Output()
    if err != nil {
        if exitErr, ok := err.(*exec.ExitError); ok {
            return "", fmt.Errorf("jq command failed: %w, stderr: %s", err, string(exitErr.Stderr))
        }
        return "", fmt.Errorf("failed to execute jq command: %w", err)
    }

    // Step 3: Write the output to the specified file
    err = os.WriteFile(outputFile, jqOutput, 0644)
    if err != nil {
        return "", fmt.Errorf("failed to write output file: %w", err)
    }

    return string(jqOutput), nil
}

// bytesReader converts a byte slice to a reader for piping between commands
func bytesReader(data []byte) *os.File {
    // Use an in-memory pipe to avoid temporary files
    r, w, err := os.Pipe()
    if err != nil {
        return nil
    }
    go func() {
        defer w.Close()
        w.Write(data)
    }()
    return r
}

