// QuerySLBAndExport executes the aliyun CLI command to describe SLB,
// processes the output with jq, and saves it to the specified file.
// Returns the stdout of the command pipeline and any error encountered.
func QuerySLBAndExport(loadBalancerName string, outputFile string) (string, error) {
	// First command: aliyun slb DescribeLoadBalancers --LoadBalancerName <name>
	aliyunCmd := exec.Command("aliyun", "slb", "DescribeLoadBalancers", "--LoadBalancerName", loadBalancerName)

	// Second command: jq '.LoadBalancers.LoadBalancer[]'
	jqCmd := exec.Command("jq", ".LoadBalancers.LoadBalancer[]")

	// Pipe aliyunCmd's stdout to jqCmd's stdin
	pipe, err := aliyunCmd.StdoutPipe()
	if err != nil {
		return "", fmt.Errorf("failed to create stdout pipe for aliyun: %w", err)
	}
	jqCmd.Stdin = pipe

	// Capture jqCmd's stdout
	jqOutput, err := jqCmd.StdoutPipe()
	if err != nil {
		return "", fmt.Errorf("failed to create stdout pipe for jq: %w", err)
	}

	// Start jqCmd first so it's ready to read from the pipe
	if err := jqCmd.Start(); err != nil {
		return "", fmt.Errorf("failed to start jq: %w", err)
	}

	// Start aliyunCmd
	if err := aliyunCmd.Start(); err != nil {
		jqCmd.Wait()
		return "", fmt.Errorf("failed to start aliyun: %w", err)
	}

	// Wait for aliyunCmd to finish
	if err := aliyunCmd.Wait(); err != nil {
		jqCmd.Wait()
		return "", fmt.Errorf("aliyun command failed: %w", err)
	}

	// Read jq output
	outputBytes := make([]byte, 0)
	buf := make([]byte, 4096)
	for {
		n, err := jqOutput.Read(buf)
		if n > 0 {
			outputBytes = append(outputBytes, buf[:n]...)
		}
		if err != nil {
			break
		}
	}

	// Wait for jqCmd to finish
	if err := jqCmd.Wait(); err != nil {
		return string(outputBytes), fmt.Errorf("jq command failed: %w, output: %s", err, string(outputBytes))
	}

	// Write the output to the specified file safely
	if err := os.WriteFile(outputFile, outputBytes, 0644); err != nil {
		return string(outputBytes), fmt.Errorf("failed to write output file: %w", err)
	}

	return string(outputBytes), nil
}

