// QuerySLBAndExport executes the aliyun CLI command to describe SLB,
// processes the output with jq, and saves it to the specified file.
// Returns the stdout of the command pipeline and any error encountered.
func QuerySLBAndExport(loadBalancerName string, outputFile string) (string, error) {
    // Step 1: Run aliyun slb command
    aliyunCmd := exec.Command("aliyun", "slb", "DescribeLoadBalancers",
        "--LoadBalancerName", loadBalancerName)

    // Step 2: Run jq to filter the output
    jqCmd := exec.Command("jq", ".LoadBalancers.LoadBalancer[]")

    // Create pipe between aliyun and jq
    pipe, err := aliyunCmd.StdoutPipe()
    if err != nil {
        return "", fmt.Errorf("failed to create stdout pipe for aliyun: %w", err)
    }
    jqCmd.Stdin = pipe

    // Step 3: Open the output file for writing
    outFile, err := os.Create(outputFile)
    if err != nil {
        return "", fmt.Errorf("failed to create output file: %w", err)
    }
    defer outFile.Close()

    jqCmd.Stdout = outFile

    // Capture stderr from jq
    var jqStderr strings.Builder
    jqCmd.Stderr = &jqStderr

    // Capture aliyun command output
    var aliyunOutput strings.Builder
    aliyunCmd.Stderr = &aliyunOutput

    // Start jq first
    if err := jqCmd.Start(); err != nil {
        return "", fmt.Errorf("failed to start jq: %w", err)
    }

    // Start aliyun command
    if err := aliyunCmd.Start(); err != nil {
        return "", fmt.Errorf("failed to start aliyun: %w", err)
    }

    // Wait for aliyun to finish
    aliyunErr := aliyunCmd.Wait()

    // Wait for jq to finish
    jqErr := jqCmd.Wait()

    if aliyunErr != nil {
        return aliyunOutput.String(), fmt.Errorf("aliyun command failed: %w, output: %s", aliyunErr, aliyunOutput.String())
    }

    if jqErr != nil {
        return aliyunOutput.String(), fmt.Errorf("jq command failed: %w, stderr: %s", jqErr, jqStderr.String())
    }

    return aliyunOutput.String(), nil
}

