package main

import (
	"fmt"
	"os/exec"
	"strings"
)

// QuerySLBAndExport queries SLB information using aliyun CLI and exports formatted output.
// It runs: aliyun slb DescribeLoadBalancers --LoadBalancerName NAME | jq '.LoadBalancers.LoadBalancer[]' > outputFile
func QuerySLBAndExport(loadBalancerName string, outputFile string) (string, error) {
	// Build the aliyun command
	aliyunCmd := exec.Command("aliyun", "slb", "DescribeLoadBalancers", "--LoadBalancerName", loadBalancerName)

	// Build the jq command
	jqCmd := exec.Command("jq", ".LoadBalancers.LoadBalancer[]")

	// Create a pipe between aliyun and jq
	jqCmd.Stdin, _ = aliyunCmd.StdoutPipe()

	// Capture jq's stdout
	var jqOutput strings.Builder
	jqCmd.Stdout = &jqOutput

	// Capture jq's stderr for error reporting
	var jqStderr strings.Builder
	jqCmd.Stderr = &jqStderr

	// Start jq first
	if err := jqCmd.Start(); err != nil {
		return "", fmt.Errorf("failed to start jq command: %w", err)
	}

	// Start aliyun
	if err := aliyunCmd.Start(); err != nil {
		return "", fmt.Errorf("failed to start aliyun command: %w", err)
	}

	// Wait for aliyun to finish
	aliyunErr := aliyunCmd.Wait()

	// Wait for jq to finish
	jqErr := jqCmd.Wait()

	// Check for errors
	if aliyunErr != nil {
		return "", fmt.Errorf("aliyun command failed: %w", aliyunErr)
	}
	if jqErr != nil {
		return "", fmt.Errorf("jq command failed: %w, stderr: %s", jqErr, jqStderr.String())
	}

	// Get the output
	output := jqOutput.String()

	// Write to output file using shell redirection
	writeCmd := exec.Command("bash", "-c", fmt.Sprintf("echo '%s' > %s", strings.ReplaceAll(output, "'", "'\\''"), outputFile))
	writeOutput, err := writeCmd.CombinedOutput()
	if err != nil {
		return "", fmt.Errorf("failed to write to output file: %w, output: %s", err, string(writeOutput))
	}

	return output, nil
}

func main() {
	// Example usage
	result, err := QuerySLBAndExport("my-load-balancer", "output.json")
	if err != nil {
		fmt.Printf("Error: %v\n", err)
		return
	}
	fmt.Printf("Query result:\n%s\n", result)
}

